mapper.select:
select r.reservation_id, r.user_id, r.room_id, r.seat_id, rm.room_name, s.seat_no,
       r.start_time, r.end_time, r.check_deadline, r.status
from seatflow_reservation r
inner join seatflow_room rm on rm.room_id = r.room_id
inner join seatflow_seat s on s.seat_id = r.seat_id
where r.user_id = #{userId}
  and r.status = 'pending_checkin'
  and r.start_time <= #{now}
  and r.check_deadline >= #{now}
order by r.start_time asc

mapper.update:
update seatflow_reservation
set status = 'in_use', update_time = #{now}
where reservation_id = #{reservationId}
  and status = 'pending_checkin'

update seatflow_reservation
set status = 'no_show', update_time = #{now}
where reservation_id = #{reservationId}
  and status = 'pending_checkin'
  and check_deadline < #{now}

mapper.select:
select violation_id
from seatflow_violation_record
where reservation_id = #{reservationId}

mapper.update:
update seatflow_user_profile
set violation_count = violation_count + 1, update_time = current_timestamp
where user_id = #{userId}
